 type BluntDBStorage struct {
 	db *badger.DB
 }

 func NewBluntDBStorage(path string) (*BluntDBStorage, error) {
 	// Expand ~ to home directory if present
 	if strings.HasPrefix(path, "~") {
 		homeDir, err := os.UserHomeDir()
 		if err != nil {
 			return nil, fmt.Errorf("failed to get home directory: %w", err)
 		}
 		path = filepath.Join(homeDir, path[1:])
 	}

 	// Ensure directory exists with proper permissions
 	if err := os.MkdirAll(path, 0755); err != nil {
 		return nil, fmt.Errorf("failed to create storage directory %s: %w", path, err)
 	}

 	opts := badger.DefaultOptions(path)
 	opts.Logger = nil // Disable badger logging

 	db, err := badger.Open(opts)
 	if err != nil {
 		return nil, fmt.Errorf("failed to open BluntDB at %s: %w", path, err)
 	}

 	return &BluntDBStorage{db: db}, nil
 }

 func (s *BluntDBStorage) Put(key, value []byte) error {
 	return s.db.Update(func(txn *badger.Txn) error {
 		return txn.Set(key, value)
 	})
 }

 func (s *BluntDBStorage) Get(key []byte) ([]byte, error) {
 	var value []byte
 	err := s.db.View(func(txn *badger.Txn) error {
 		item, err := txn.Get(key)
 		if err != nil {
 			if err == badger.ErrKeyNotFound {
 				return ErrNotFound
 			}
 			return err
 		}

 		return item.Value(func(val []byte) error {
 			value = append([]byte{}, val...)
 			return nil
 		})
 	})

 	return value, err
 }

 func (s *BluntDBStorage) Delete(key []byte) error {
 	return s.db.Update(func(txn *badger.Txn) error {
 		return txn.Delete(key)
 	})
 }

 func (s *BluntDBStorage) Has(key []byte) (bool, error) {
 	err := s.db.View(func(txn *badger.Txn) error {
 		_, err := txn.Get(key)
 		return err
 	})

 	if err == badger.ErrKeyNotFound {
 		return false, nil
 	}
 	if err != nil {
 		return false, err
 	}
 	return true, nil
 }

 func (s *BluntDBStorage) Close() error {
 	return s.db.Close()
 }

 func (s *BluntDBStorage) Batch() Batch {
 	return &BluntDBBatch{
 		db:      s.db,
 		entries: make(map[string][]byte),
 		deletes: make(map[string]bool),
 	}
 }

+// KB index prefix operations
+const KBIndexPrefix = "kb_index_"
+
+func (s *BluntDBStorage) PutKBIndex(kbID string, data []byte) error {
+	key := KBIndexPrefix + kbID
+	return s.Put([]byte(key), data)
+}
+
+func (s *BluntDBStorage) GetKBIndex(kbID string) ([]byte, error) {
+	key := KBIndexPrefix + kbID
+	return s.Get([]byte(key))
+}
+
+func (s *BluntDBStorage) ListKBIndexes() ([]string, error) {
+	var ids []string
+	err := s.db.View(func(txn *badger.Txn) error {
+		opts := badger.DefaultIteratorOptions
+		opts.Prefix = []byte(KBIndexPrefix)
+		it := txn.NewIterator(opts)
+		defer it.Close()
+		for it.Seek([]byte(KBIndexPrefix)); it.ValidForPrefix([]byte(KBIndexPrefix)); it.Next() {
+			key := string(it.Item().Key())
+			id := strings.TrimPrefix(key, KBIndexPrefix)
+			ids = append(ids, id)
+		}
+		return nil
+	})
+	if err != nil {
+		return nil, err
+	}
+	return ids, nil
+}
+
+func (s *BluntDBStorage) DeleteKBIndex(kbID string) error {
+	key := KBIndexPrefix + kbID
+	return s.Delete([]byte(key))
+}
+
