 func (h *KnirvGraphHandlers) GetErrorNodes(w http.ResponseWriter, r *http.Request) {
 	var nodes []map[string]interface{}

 	err := h.db.GetObjectsByPrefix("knirvgraph:error_nodes:", func(key string, value []byte) bool {
