+                        <span>{formatTime(errorNode.timestamp)}</span>
+                      </div>
+                    </div>
+                  </div>
+                  <div className={styles.errorHeaderRight}>
+                    <div className={`${styles.severityBadge} ${getSeverityColor(errorNode.severity)}`}>
